package ca.yorku.eecs3311.coursepilot.application.agent; import org.springframework.stereotype.Component; import java.util.*; @Component public class AgentPlanValidator {private static final Set<String> ALLOWED=Set.of("COURSE_SEARCH","GET_PROGRESS","GET_WEAK_TOPICS","GET_STUDY_PLAN","GET_HISTORY","GET_RECOMMENDATION","GENERATE_SUMMARY","GENERATE_FLASHCARDS","GENERATE_QUIZ","CREATE_STUDY_PLAN");public void validate(AgentPlan plan,Long courseId){if(courseId==null)throw new IllegalArgumentException("A course is required for agent assistance.");if(plan==null||plan.steps().isEmpty()||plan.steps().size()>5)throw new IllegalArgumentException("Agent plan must contain between 1 and 5 steps.");for(AgentPlanStep step:plan.steps())if(!ALLOWED.contains(step.tool()))throw new IllegalArgumentException("Unsupported agent tool: "+step.tool());}}
